input.old_string:
* { box-sizing: border-box }
*:focus { outline: none }
body { margin: 0; font-family: system-ui, sans-serif; background: #fff; color: #22272e }

input.new_string:
* { box-sizing: border-box }
*:focus-visible { outline: 2px solid #2456c4; outline-offset: 2px }
body { margin: 0; font-family: system-ui, sans-serif; background: #fff; color: #22272e }

